import clsx from 'clsx';
import React from 'react';

import { CriticalIcon } from '@dynatrace/strato-icons';

import type { DataTestId } from '../../../../core/types/data-props.js';
import type { DOMProps } from '../../../../core/types/dom.js';
import type { StylingProps } from '../../../../core/types/styling-props.js';
import type { WithChildren } from '../../../../core/types/with-children.js';
import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { useFormFieldMessagesContext } from '../../hooks/useFormFieldMessagesContext.js';
import { FormFieldMessageItemCSS } from '../styles/FormFieldMessageItem.sty.js';

export interface FormFieldMessageBaseItemProps
  extends WithChildren,
    StylingProps,
    DOMProps,
    DataTestId {
  /**
   * Determines the style of the message (text color, icon).
   * Error messages additionally prevent the form component
   * from being submitted in a form.
   */
  variant?: 'error' | 'hint';
  /**
   * Whether the connected input is currently disabled.
   * @defaultValue false
   */
  disabled?: boolean;
}

/** Renders a Form Field Message. */
export const _BaseItem = (props: FormFieldMessageBaseItemProps) => {
  const {
    children,
    variant = 'hint',
    className: consumerClassName,
    style: consumerStyle,
    disabled: propDisabled = false,
    'data-testid': dataTestId,
    id: propId,
  } = props;

  const { disabled: contextDisabled } = useFormFieldMessagesContext();
  const disabled = propDisabled || contextDisabled;

  return (
    <Flex
      className={clsx(
        FormFieldMessageItemCSS({ variant, disabled }),
        consumerClassName,
      )}
      style={consumerStyle}
      alignItems="flex-start"
      gap={4}
      data-testid={dataTestId}
      id={propId}
    >
      {variant === 'error' && (
        <Flex>
          <CriticalIcon size="small" />
        </Flex>
      )}
      <div>{children}</div>
    </Flex>
  );
};

_BaseItem.displayName = 'FormFieldMessageItem';
